const fs = require('node:fs');
const path = require('node:path');

const PACKAGE_ROOT = path.resolve(__dirname, '../..');
const PREVIEWS_ROOT = path.join(PACKAGE_ROOT, 'examples/previews');
const SECTIONS_PATH = path.join(PREVIEWS_ROOT, 'sections.json');
const REGISTRY_PATH = path.join(PREVIEWS_ROOT, 'registry.tsx');
const DOC_COMPONENTS_DIR = path.join(PACKAGE_ROOT, 'docs/components');
const SIDEBARS_PATH = path.join(PACKAGE_ROOT, 'sidebars.generated.cjs');
const DOC_ID_PREFIX = 'components/';
const GENERATED_DOC_MARKER =
  '{/* AUTO-GENERATED by scripts/sync-previews.cjs. Do not edit. */}';
const GENERATED_SOURCE_MARKER =
  '// AUTO-GENERATED by scripts/sync-previews.cjs. Do not edit.';
const GENERATED_SIDEBARS_MARKER = GENERATED_SOURCE_MARKER;
const ID_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const DOC_ID_PATTERN =
  /^components\/[a-z0-9]+(?:-[a-z0-9]+)*\/[a-z0-9]+(?:-[a-z0-9]+)*$/;

function fail(message) {
  throw new Error(message);
}

function toDisplayPath(filePath) {
  return path.relative(PACKAGE_ROOT, filePath);
}

function assertString(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    fail(`${label} 必须是非空字符串`);
  }
}

function assertId(value, label) {
  assertString(value, label);

  if (!ID_PATTERN.test(value)) {
    fail(`${label} 必须使用小写 kebab-case：${value}`);
  }
}

function readJson(filePath) {
  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (error) {
    fail(
      `读取 ${toDisplayPath(filePath)} 失败：${
        error instanceof Error ? error.message : String(error)
      }`,
    );
  }
}

function quote(value) {
  return `'${String(value)
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\r/g, '\\r')
    .replace(/\n/g, '\\n')}'`;
}

module.exports = {
  DOC_COMPONENTS_DIR,
  DOC_ID_PATTERN,
  DOC_ID_PREFIX,
  GENERATED_DOC_MARKER,
  GENERATED_SIDEBARS_MARKER,
  GENERATED_SOURCE_MARKER,
  ID_PATTERN,
  PACKAGE_ROOT,
  PREVIEWS_ROOT,
  REGISTRY_PATH,
  SECTIONS_PATH,
  SIDEBARS_PATH,
  assertId,
  assertString,
  fail,
  quote,
  readJson,
  toDisplayPath,
};
